def sha(path):
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(65536), b""):
            h.update(block)
    return h.hexdigest()


def cfg(path):
    result = {}
    for line in path.read_text().splitlines():
        line = line.split("#", 1)[0]
        if "=" in line:
            k, v = line.split("=", 1);result[k.strip()] = v.strip()
    return result


def rows(path, delimiter=","):
