def monitoring_costs(records):
    """Verify the new GNU-time CT summary, keeping historical scopes separate."""
    summary = records.load("monitoring/summary.json")
    issues, rows = [], summary.get("CT_current_case_receipts")
    if not isinstance(rows, list) or not isinstance(summary.get("counting_limits"), list):
        return dict(ready=False, listed_receipts_verified=False, issues=["Legacy or unrecognized monitoring summary schema"], summary={})
    verified, successful, walls, peak_rss, failed = 0., 0., 0., 0., []
    expected_paths = set()
    for row in rows:
        relative = row.get("receipt", "")
        path = (records.root/relative).resolve()
        if not relative or Path(relative).is_absolute() or not path.is_relative_to((records.root/"results").resolve()) or not path.is_file() or sha(path) != row.get("receipt_sha256"):
            issues.append("Stale/missing GNU-time receipt: "+relative);continue
        usage = json.loads(path.read_text())
        times = [usage.get(key) for key in ("user_seconds", "system_seconds", "wall_seconds_including_inputs")]
        if usage.get("gnu_time_resource_complete") is not True or not all(finite(value) and value >= 0 for value in times):
            issues.append("Incomplete GNU-time receipt: "+relative);continue
        cpu = times[0]+times[1]
        success = usage.get("exit_code") == 0
        if not all(finite(row.get(key)) and math.isclose(row[key], actual, rel_tol=1e-10, abs_tol=1e-8) for key, actual in (("CPU_seconds", cpu), ("wall_seconds", times[2]))) or row.get("successful_execution") is not success or row.get("peak_RSS_KiB") != usage.get("maxrss_kb"):
            issues.append("Cost/status mismatch: "+relative);continue
        expected_paths.add(relative);records.read[relative] = row["receipt_sha256"]
        verified += cpu;walls += times[2]
        peak_rss = max(peak_rss, usage.get("maxrss_kb") or 0)
        if success:
            successful += cpu
        else:
            failed.append(row.get("case"))
    for key, actual in (("CT_CPU_seconds_including_recorded_failed_attempts", verified), ("CT_CPU_seconds_successful_executions", successful), ("CT_sum_recorded_run_wall_seconds", walls), ("CT_largest_recorded_native_RSS_KiB", peak_rss)):
        if not finite(summary.get(key)) or not math.isclose(summary[key], actual, rel_tol=1e-10, abs_tol=1e-8):
            issues.append("GNU-time aggregate mismatch: "+key)
    unaccounted = []
    for path in (records.root/"results").glob("ct*/runner_usage.json"):
        usage = json.loads(path.read_text())
        times = [usage.get(key) for key in ("user_seconds", "system_seconds", "wall_seconds_including_inputs")]
        if usage.get("gnu_time_resource_complete") is True and all(finite(value) and value >= 0 for value in times) and str(path.relative_to(records.root)) not in expected_paths:
            unaccounted.append(str(path.relative_to(records.root)))
    historical = summary.get("historical_provisional_accounting", {})
    historical_path = records.root/historical.get("file", "")
    historical_ok = bool(historical) and historical_path.is_file() and sha(historical_path) == historical.get("sha256")
    if historical_ok:
        records.read[historical["file"]] = historical["sha256"]
    script = records.root/"scripts/summarize_monitoring.py"
    if script.is_file():
        records.read["scripts/summarize_monitoring.py"] = sha(script)
    return dict(ready=not issues and not unaccounted, listed_receipts_verified=not issues, current_receipt_coverage_complete=not unaccounted,
                issues=issues, unaccounted_completed_receipts=unaccounted, recorded_failed_cases=failed,
                historical_accounting_separately_verified=historical_ok, summary=summary,
                scope="Current-case GNU-time CT receipts, including retained failures. Builds/tests/pilots/unfinished jobs and archived prior attempts are excluded; historical GLM accounting is separate, not added to a complete-project total.")


